#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
inline int RE(int i) { return i ^ 1; }

struct Edge {
        int v, c;
};

struct FlowSolver {
        int n, m, s, t;
        vector<int> adj[MAXN];
        Edge edges[MAXM * 2];

        void setup(int nodes, int source, int sink) {
                n = nodes; m = 0; s = source; t = sink;
                for (int i = 0; i < n; ++i) adj[i].clear();
        }

        void connect(int a, int b, int cap) {
                edges[m].v = b; edges[m].c = cap;
                adj[a].push_back(m);
                edges[m + 1].v = a; edges[m + 1].c = 0;
                adj[b].push_back(m + 1);
                m += 2;
        }

        int dist[MAXN], count[MAXN], current[MAXN], parent[MAXN], pathDepth;
        void bfs() {
                queue<int> q;
                fill(dist, dist + n, n);
                fill(count, count + n, 0);
                dist[t] = 0;
                q.push(t);
                while (!q.empty()) {
                        int u = q.front(); q.pop();
                        for (auto id : adj[u]) {
                                int v = edges[id].v;
                                if (dist[v] == n && edges[RE(id)].c > 0) {
                                        dist[v] = dist[u] + 1;
                                        q.push(v);
                                }
                        }
                }
        }

        void relabel(int v) {
                --count[dist[v]];
                dist[v] = n;
                for (size_t i = 0; i < adj[v].size(); ++i) {
                        auto &arc = edges[adj[v][i]];
                        if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                                dist[v] = dist[arc.v] + 1;
                                parent[v] = i;
                        }
                }
                ++count[dist[v]];
        }

        int pushFlow() {
                int flow = INT_MAX;
                int idx = -1;
                for (int i = 0; i < pathDepth; ++i) {
                        auto &arc = edges[adj[parent[edges[adj[parent[0]]][0]]][i]];
                        if (arc.c < flow) {
                                flow = arc.c;
                                idx = i;
                        }
                }
                for (int i = 0; i < pathDepth; ++i) {
                        int id = adj[parent[edges[adj[parent[0]]][i]]][i];
                        edges[id].c -= flow;
                        edges[RE(id)].c += flow;
                }
                pathDepth = idx;
                return flow;
        }

        int maxFlow() {
                int totalFlow = 0;
                bfs();
                fill(current, current + n, 0);
                int u = s;
                parent[s] = -1;
                while (dist[s] != n) {
                        if (u == t) {
                                totalFlow += pushFlow();
                                u = s;
                                continue;
                        }
                        bool advanced = false;
                        for (; current[u] < (int)adj[u].size(); ++current[u]) {
                                auto &arc = edges[adj[u][current[u]]];
                                if (dist[arc.v] == dist[u] - 1 && arc.c > 0) {
                                        parent[arc.v] = u;
                                        u = arc.v;
                                        pathDepth++;
                                        advanced = true;
                                        break;
                                }
                        }
                        if (!advanced) {
                                if (count[dist[u]] == 1) break;
                                relabel(u);
                                if (u != s) {
                                        --pathDepth;
                                        u = edges[parent[u]].v;
                                }
                        }
                }
                return totalFlow;
        }
} fn;

const int MAXNODES = 12;
const int INF = 1000000007;
const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, -1, 0, 1};

int n;
char grid[MAXNODES][MAXNODES], result[MAXNODES][MAXNODES];
int dist_map[MAXNODES][MAXNODES], time_map[MAXNODES][MAXNODES];

inline int nodeX(int i, int j) { return i * MAXNODES + j; }
inline int nodeY(int i, int j) { return MAXNODES * MAXNODES + i * MAXNODES + j; }
inline int sourceNode() { return MAXNODES * MAXNODES; }
inline int sinkNode() { return sourceNode() + 1; }
inline int totalNodes() { return sinkNode() + 1; }

void computeDistances(int size) {
        queue<pair<int, int>> q;
        for (int i = 0; i < size; ++i) {
                for (int j = 0; j < size; ++j) {
                        dist_map[i][j] = INF;
                        if (grid[i][j] == 'Z') {
                                q.push({i, j});
                                dist_map[i][j] = 0;
                        }
                }
        }
        while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                for (int k = 0; k < 4; ++k) {
                        int xx = x + dx[k], yy = y + dy[k];
                        if (0 <= xx && xx < size && 0 <= yy && yy < size
                            && isdigit(grid[xx][yy]) && dist_map[xx][yy] == INF) {
                                dist_map[xx][yy] = dist_map[x][y] + 1;
                                q.push({xx, yy});
                        }
                }
        }
}

void process(int size, int maxDist, int startX, int startY) {
        queue<pair<int, int>> q;
        for (int i = 0; i < size; ++i)
                for (int j = 0; j < size; ++j)
                        time_map[i][j] = INF;
        q.push({startX, startY});
        time_map[startX][startY] = 0;
        while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                if (time_map[x][y] > maxDist) break;
                if (time_map[x][y] <= dist_map[x][y] && isdigit(result[x][y]) && result[x][y] != '0') {
                        fn.addEdge(nodeX(startX, startY), nodeY(x, y), 11);
                }
                if (time_map[x][y] >= dist_map[x][y]) continue;
                for (int k = 0; k < 4; ++k) {
                        int xx = x + dx[k], yy = y + dy[k];
                        if (0 <= xx && xx < size && 0 <= yy && yy < size
                            && isdigit(grid[xx][yy]) && time_map[xx][yy] == INF) {
                                time_map[xx][yy] = time_map[x][y] + 1;
                                q.push({xx, yy});
                        }
                }
        }
}

int main() {
        int size, maxDist;
        scanf("%d%d", &size, &maxDist);
        fn.setup(totalNodes(), sourceNode(), sinkNode());
        for (int i = 0; i < size; ++i) {
                scanf("%s", grid[i]);
                for (int j = 0; j < size; ++j) {
                        if (isdigit(grid[i][j]) && grid[i][j] != '0') {
                                fn.connect(sourceNode(), nodeX(i, j), grid[i][j] - '0');
                        }
                }
        }
        for (int i = 0; i < size; ++i) {
                scanf("%s", result[i]);
                for (int j = 0; j < size; ++j) {
                        if (isdigit(result[i][j]) && result[i][j] != '0') {
                                fn.connect(nodeY(i, j), sinkNode(), result[i][j] - '0');
                        }
                }
        }
        computeDistances(size);
        for (int i = 0; i < size; ++i) {
                for (int j = 0; j < size; ++j) {
                        if (isdigit(grid[i][j]) && grid[i][j] != '0') {
                                process(size, maxDist, i, j);
                        }
                }
        }
        printf("%d\n", fn.maxFlow());
        return 0;
}
